/****** Object:  UserDefinedFunction [dbo].[fn_LoHongDaXuLy]    Script Date: 6/26/2026 3:51:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_LoHongDaXuLy]
(
    @TrangThaiKhacPhuc NVARCHAR(20)
)
RETURNS BIT
AS
BEGIN
    DECLARE @s NVARCHAR(20) = LTRIM(RTRIM(ISNULL(@TrangThaiKhacPhuc, N'')));
    IF @s IN (N'Đã vá', N'Đã xử lý')
        RETURN 1;
    RETURN 0;
END;
GO
/****** Object:  UserDefinedFunction [dbo].[fn_SuCoDaXuLy]    Script Date: 6/26/2026 3:51:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_SuCoDaXuLy]
(
    @DaXuLy BIT
)
RETURNS BIT
AS
BEGIN
    IF CONVERT(INT, ISNULL(@DaXuLy, 0)) <> 0
        RETURN 1;
    RETURN 0;
END;
GO
