CREATE   PROCEDURE [dbo].[sp_GetAvailability] 
AS SELECT T.TenTB, CAST(COUNT(CASE WHEN C.MatGoi < 100 THEN 1 END) * 100.0 / NULLIF(COUNT(C.MaCS),0) AS DECIMAL(5,2)) AS UptimePercent FROM ThietBi T LEFT JOIN ChiSoHieuSuat C ON T.MaTB = C.MaTB GROUP BY T.TenTB;
