/* ---------------------------------------------------------
   SP 4: Lay nhat ky loi (cho tab Nhat ky loi)
   --------------------------------------------------------- */
CREATE   PROCEDURE [dbo].[sp_GetErrorLog]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        N.MaLoi,
        N.MaTB,
        N.ThoiGianLoi,
        N.MoTaLoi,
        N.MucDoNghiemTrong,
        N.MaNV_XuLy,
        T.TenTB,
        NV.HoTen
    FROM dbo.NhatKyLoi N
    LEFT JOIN dbo.ThietBi T ON N.MaTB = T.MaTB
    LEFT JOIN dbo.NhanVien NV ON N.MaNV_XuLy = NV.MaNV
    ORDER BY N.ThoiGianLoi DESC, N.MaLoi DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[sp_GetErrorTrend]    Script Date: 6/26/2026 3:51:53 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[sp_GetErrorTrend]
AS
BEGIN
    SELECT 
        CAST(ThoiGianLoi AS DATE) AS Ngay,
        COUNT(*) AS TongSoSuCo,
        AVG(CAST(MucDoNghiemTrong AS FLOAT)) AS MucDoTrungBinh,
        COUNT(CASE WHEN MucDoNghiemTrong >= 4 THEN 1 END) AS Critical,
        COUNT(CASE WHEN MucDoNghiemTrong >= 3 AND MucDoNghiemTrong < 4 THEN 1 END) AS High,
        COUNT(CASE WHEN MucDoNghiemTrong >= 2 AND MucDoNghiemTrong < 3 THEN 1 END) AS Medium,
        COUNT(CASE WHEN MucDoNghiemTrong < 2 THEN 1 END) AS Low
    FROM NhatKyLoi
    WHERE ThoiGianLoi IS NOT NULL
    GROUP BY CAST(ThoiGianLoi AS DATE)
    ORDER BY Ngay DESC
END
GO
