CREATE PROCEDURE [dbo].[sp_GetTopEmployees]
AS
BEGIN
    SELECT TOP 5
        NV.HoTen,
        NV.Email,
        NV.VaiTro,
        COUNT(N.MaLoi) AS TongSoSuCo,
        CAST(AVG(CAST(N.MucDoNghiemTrong AS FLOAT)) AS DECIMAL(5,2)) AS MucDoTrungBinh
    FROM NhanVien NV
    LEFT JOIN NhatKyLoi N ON NV.MaNV = N.MaNV_XuLy
    GROUP BY NV.MaNV, NV.HoTen, NV.Email, NV.VaiTro
    ORDER BY TongSoSuCo DESC
END
GO
