GO

/* ---------------------------------------------------------
   - Chan xoa lo hong neu TrangThaiKhacPhuc:
     + Chưa vá
     + Đang xử lý
   - Chi cho xoa khi da xu ly xong
   --------------------------------------------------------- */
CREATE   TRIGGER [dbo].[trg_BlockDeleteVulnerability_Unresolved]
ON [dbo].[LoHong]
INSTEAD OF DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF CONTEXT_INFO() = 0x4E474154
    BEGIN
        DELETE l
        FROM dbo.LoHong l
        JOIN deleted d ON l.MaLH = d.MaLH;
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM deleted d
        JOIN dbo.LoHong l ON l.MaLH = d.MaLH
        WHERE l.TrangThaiKhacPhuc IN (N'Chưa vá', N'Đang xử lý')
    )
    BEGIN
        RAISERROR (N'Khong duoc xoa lo hong khi chua xu ly xong (Chua va/Dang xu ly).', 16, 1);
        RETURN;
    END;

    DELETE l
    FROM dbo.LoHong l
    JOIN deleted d ON l.MaLH = d.MaLH;
END;
GO
ALTER TABLE [dbo].[LoHong] ENABLE TRIGGER [trg_BlockDeleteVulnerability_Unresolved]
