/****** Object:  Trigger [dbo].[trg_LimitEmployeeVulnerabilityCases]    Script Date: 6/26/2026 3:51:56 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* ---------------------------------------------------------
    - Trigger INSERT/UPDATE tren bang LoHong.
   - Ngăn chặn nhân viên được gán quá 3 lỗ hổng CHƯA HOÀN TẤT.
   --------------------------------------------------------- */
CREATE   TRIGGER [dbo].[trg_LimitEmployeeVulnerabilityCases]
ON [dbo].[LoHong]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF COL_LENGTH('dbo.LoHong', 'MaNV_XuLy') IS NULL
        RETURN;

    IF EXISTS (
        SELECT TOP 1 l.MaNV_XuLy
        FROM dbo.LoHong l
        WHERE l.MaNV_XuLy IN (
            SELECT DISTINCT i.MaNV_XuLy
            FROM inserted i
            WHERE i.MaNV_XuLy IS NOT NULL
              AND ISNULL(i.TrangThaiKhacPhuc, N'Chưa vá') IN (N'Chưa vá', N'Đang xử lý')
        )
          AND ISNULL(l.TrangThaiKhacPhuc, N'Chưa vá') IN (N'Chưa vá', N'Đang xử lý')
        GROUP BY l.MaNV_XuLy
        HAVING COUNT(*) > 3
    )
    BEGIN
        RAISERROR (N'Khong the phan cong lo hong: moi nhan vien chi duoc xu ly toi da 3 case chua hoan tat.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO
ALTER TABLE [dbo].[LoHong] ENABLE TRIGGER [trg_LimitEmployeeVulnerabilityCases]
GO
/****** Object:  Trigger [dbo].[trg_ValidateVulnerabilityTimes]    Script Date: 6/26/2026 3:51:56 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* ---------------------------------------------------------
   - Trigger INSERT/UPDATE tren bang LoHong.
   - Rang buoc thoi gian:
     + ThoiGianXuLySuCo PHAI sau hoac bang ThoiGianXayRaSuCo.
     + Khoang cach giua 2 cot moc thoi gian KHONG duoc qua 24 gio.
   --------------------------------------------------------- */
CREATE   TRIGGER [dbo].[trg_ValidateVulnerabilityTimes]
ON [dbo].[LoHong]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE i.ThoiGianXayRaSuCo IS NOT NULL
          AND i.ThoiGianXuLySuCo IS NOT NULL
          AND i.ThoiGianXuLySuCo < i.ThoiGianXayRaSuCo
    )
    BEGIN
        RAISERROR (N'Thoi gian xu ly su co phai sau hoac bang thoi gian xay ra su co.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE i.ThoiGianXayRaSuCo IS NOT NULL
          AND i.ThoiGianXuLySuCo IS NOT NULL
          AND DATEDIFF(MINUTE, i.ThoiGianXayRaSuCo, i.ThoiGianXuLySuCo) > 1440
    )
    BEGIN
        RAISERROR (N'Thoi gian xu ly su co khong duoc qua 24 gio ke tu thoi gian xay ra su co.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO
ALTER TABLE [dbo].[LoHong] ENABLE TRIGGER [trg_ValidateVulnerabilityTimes]
GO
/****** Object:  Trigger [dbo].[trg_BlockDeleteAdminEmployee]    Script Date: 6/26/2026 3:51:56 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   TRIGGER [dbo].[trg_BlockDeleteAdminEmployee]
ON [dbo].[NhanVien]
INSTEAD OF DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM deleted d
        JOIN dbo.NhanVien nv ON nv.MaNV = d.MaNV
        WHERE nv.VaiTro = N'Admin'
    )
    BEGIN
        RAISERROR (N'Khong duoc xoa nhan vien co vai tro Admin.', 16, 1);
        RETURN;
    END;

    UPDATE nkl
    SET nkl.MaNV_XuLy = NULL
    FROM dbo.NhatKyLoi nkl
    JOIN deleted d ON nkl.MaNV_XuLy = d.MaNV;

    IF COL_LENGTH('dbo.LoHong', 'MaNV_XuLy') IS NOT NULL
    BEGIN
        UPDATE l
        SET l.MaNV_XuLy = NULL
        FROM dbo.LoHong l
        JOIN deleted d ON l.MaNV_XuLy = d.MaNV;
    END;

    IF COL_LENGTH('dbo.LienKet', 'MaNV_Tao') IS NOT NULL
    BEGIN
        UPDATE lk
        SET lk.MaNV_Tao = NULL
        FROM dbo.LienKet lk
        JOIN deleted d ON lk.MaNV_Tao = d.MaNV;
    END;

    DELETE nv
    FROM dbo.NhanVien nv
    JOIN deleted d ON nv.MaNV = d.MaNV;
END;
GO
