/* =========================================================
   Trigger: chi cho xoa su co khi DaXuLy = 1
   ========================================================= */
CREATE   TRIGGER [dbo].[trg_BlockDeleteErrorLog_WhenUnresolved]
ON [dbo].[NhatKyLoi]
INSTEAD OF DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM deleted d
        JOIN dbo.NhatKyLoi n ON n.MaLoi = d.MaLoi
        WHERE ISNULL(n.DaXuLy, 0) = 0
    )
    BEGIN
        RAISERROR (N'Chi duoc xoa su co khi da xu ly.', 16, 1);
        RETURN;
    END;

    DELETE n
    FROM dbo.NhatKyLoi n
    JOIN deleted d ON n.MaLoi = d.MaLoi;
END;
GO
ALTER TABLE [dbo].[NhatKyLoi] ENABLE TRIGGER [trg_BlockDeleteErrorLog_WhenUnresolved]
GO
