/* ---------------------------------------------------------
   Chi chan khi con NhatKyLoi chua xu ly (DaXuLy=0).
   --------------------------------------------------------- */
CREATE   TRIGGER [dbo].[trg_BlockDeleteDevice]
ON [dbo].[ThietBi]
INSTEAD OF DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM deleted d
        WHERE EXISTS (
            SELECT 1
            FROM dbo.NhatKyLoi n
            WHERE n.MaTB = d.MaTB
              AND ISNULL(n.DaXuLy, 0) = 0
        )
    )
    BEGIN
        RAISERROR (N'Không thể xóa thiết bị khi còn sự cố chưa xử lý (nhật ký lỗi).', 16, 1);
        RETURN;
    END;

    DECLARE @ctx VARBINARY(128) = ISNULL(
        CONTEXT_INFO(),
        CAST(REPLICATE(0x00, 128) AS VARBINARY(128))
    ),
        @ngat VARBINARY(128) = 0x4E474154;
    SET CONTEXT_INFO @ngat;

    DELETE lk
    FROM dbo.LienKet lk
    JOIN deleted d ON lk.MaTB_Goc = d.MaTB OR lk.MaTB_Dich = d.MaTB;

    DELETE l
    FROM dbo.LoHong l
    JOIN deleted d ON l.MaTB = d.MaTB;

    DELETE c
    FROM dbo.ChiSoHieuSuat c
    JOIN deleted d ON c.MaTB = d.MaTB;

    DELETE n
    FROM dbo.NhatKyLoi n
    JOIN deleted d ON n.MaTB = d.MaTB;

    DELETE t
    FROM dbo.ThietBi t
    JOIN deleted d ON t.MaTB = d.MaTB;

    SET CONTEXT_INFO @ctx;
END;
GO
ALTER TABLE [dbo].[ThietBi] ENABLE TRIGGER [trg_BlockDeleteDevice]
GO
/****** Object:  Trigger [dbo].[trg_ValidateDeviceTypeByName]    Script Date: 6/26/2026 3:51:56 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
  Trigger kiểm tra đồng bộ Tên thiết bị và Loại thiết bị trong ThietBi:
  - Nếu tên bắt đầu bằng "Router" thì LoaiTB phải là "Router"
  - Nếu tên bắt đầu bằng "SW"/"SWL" thì LoaiTB không được là "Router"/"Firewall"
  - Nếu tên bắt đầu bằng "AS" hoặc chứa "ASA" thì LoaiTB phải là "Firewall" hoặc "ASA Firewall"
*/

CREATE   TRIGGER [dbo].[trg_ValidateDeviceTypeByName]
ON [dbo].[ThietBi]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- Rule 1: Tên Router thì loại bắt buộc là Router
    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE UPPER(LTRIM(RTRIM(ISNULL(i.TenTB, '')))) LIKE 'ROUTER%'
          AND UPPER(LTRIM(RTRIM(ISNULL(i.LoaiTB, '')))) <> 'ROUTER'
    )
    BEGIN
        RAISERROR (N'Thiet bi co ten Router thi LoaiTB bat buoc la Router.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;

    -- Rule 2: Tên SW/SWL thì không được chọn Router/Firewall
    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE (
                UPPER(LTRIM(RTRIM(ISNULL(i.TenTB, '')))) LIKE 'SW %'
             OR UPPER(LTRIM(RTRIM(ISNULL(i.TenTB, '')))) LIKE 'SWL %'
              )
          AND UPPER(LTRIM(RTRIM(ISNULL(i.LoaiTB, '')))) IN ('ROUTER', 'FIREWALL', 'ASA FIREWALL')
    )
    BEGIN
        RAISERROR (N'Thiet bi SW/SWL khong duoc chon loai Router hoac Firewall.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;

    -- Rule 3: Tên AS/ASA thì bắt buộc là Firewall/ASA Firewall
    IF EXISTS (
        SELECT 1
        FROM inserted i
        WHERE (
                UPPER(LTRIM(RTRIM(ISNULL(i.TenTB, '')))) LIKE 'AS %'
             OR UPPER(LTRIM(RTRIM(ISNULL(i.TenTB, '')))) LIKE '%ASA%'
              )
          AND UPPER(LTRIM(RTRIM(ISNULL(i.LoaiTB, '')))) NOT IN ('FIREWALL', 'ASA FIREWALL')
    )
    BEGIN
        RAISERROR (N'Thiet bi AS/ASA bat buoc chon loai Firewall (hoac ASA Firewall).', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END;
END;
GO
ALTER TABLE [dbo].[ThietBi] ENABLE TRIGGER [trg_ValidateDeviceTypeByName]
GO
